-- A promise to pay on an overdue invoice: the amount promised, the day it is promised by, and the day it was made.
ALTER TABLE invoice ADD COLUMN promise_amount DECIMAL(19, 2);
ALTER TABLE invoice ADD COLUMN promise_date DATE;
ALTER TABLE invoice ADD COLUMN promised_on DATE;
-- The rebilled invoice whose late interest the line carries onto its replacement; null for an ordinary line. Such a
-- line takes no tax, no share of the invoice discount and no surcharge.
ALTER TABLE invoice_line ADD COLUMN interest_of BIGINT;
-- The workspace's holiday calendar: once the 'holidays' setting is present (even with no rows here),
-- days in payment terms are business days, Monday to Friday and not one of these dates.
CREATE TABLE holiday (
    holiday_on DATE PRIMARY KEY
);
